function states.parse_ipsec_ah(buf, pinfo, tree, off, depth)
  depth = depth + 1
  if depth > 17 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_ipsec_ah = tree:add(pf.f_hdr_ipsec_ah, buf(math.floor(off / 8)))
  if off + 8 > avail then
    hdr_ipsec_ah:add_proto_expert_info(ef_error, "out of bounds in ipsec_ah.next_hdr")
    return off
  end
  v.v_ipsec_ah_next_hdr = buf():bitfield(off, 8)
  hdr_ipsec_ah:add(pf.f_ipsec_ah_next_hdr, buf(math.floor(off / 8), math.floor((off % 8 + 8 + 7) / 8)), v.v_ipsec_ah_next_hdr)
  off = off + 8
  if off + 8 > avail then
    hdr_ipsec_ah:add_proto_expert_info(ef_error, "out of bounds in ipsec_ah.length")
    return off
  end
  hdr_ipsec_ah:add(pf.f_ipsec_ah_length, buf(math.floor(off / 8), math.floor((off % 8 + 8 + 7) / 8)), buf():bitfield(off, 8))
  off = off + 8
  if off + 16 > avail then
    hdr_ipsec_ah:add_proto_expert_info(ef_error, "out of bounds in ipsec_ah.zero")
    return off
  end
  hdr_ipsec_ah:add(pf.f_ipsec_ah_zero, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), buf():bitfield(off, 16))
  off = off + 16
  if off + 32 > avail then
    hdr_ipsec_ah:add_proto_expert_info(ef_error, "out of bounds in ipsec_ah.spi")
    return off
  end
  hdr_ipsec_ah:add(pf.f_ipsec_ah_spi, buf(math.floor(off / 8), math.floor((off % 8 + 32 + 7) / 8)), buf():bitfield(off, 32))
  off = off + 32
