    hdr_ipsec_ah:add_proto_expert_info(ef_error, "out of bounds in ipsec_ah.seq_no")
    return off
  end
  hdr_ipsec_ah:add(pf.f_ipsec_ah_seq_no, buf(math.floor(off / 8), math.floor((off % 8 + 32 + 7) / 8)), buf():bitfield(off, 32))
  off = off + 32
  if v.v_ipsec_ah_next_hdr == 1 then
    return states.parse_icmp(buf, pinfo, tree, off, depth)
  elseif v.v_ipsec_ah_next_hdr == 6 then
    return states.parse_tcp(buf, pinfo, tree, off, depth)
  elseif v.v_ipsec_ah_next_hdr == 17 then
    return states.parse_udp(buf, pinfo, tree, off, depth)
  elseif v.v_ipsec_ah_next_hdr == 47 then
    return states.parse_gre1(buf, pinfo, tree, off, depth)
  elseif v.v_ipsec_ah_next_hdr == 58 then
    return states.parse_icmpv6(buf, pinfo, tree, off, depth)
  elseif v.v_ipsec_ah_next_hdr == 132 then
    return states.parse_sctp(buf, pinfo, tree, off, depth)
  else
    add_payload(buf, tree, off)
    return off
  end
end

